/** Default art, or skin `skin` (1-based) when the hero has one. */
export function heroArt(id: string, skin = 0): string | undefined {
  return (skin > 0 ? HERO_SKINS[id]?.[skin - 1] : undefined) ?? HERO_ART[id];
}

export function heroSkins(id: string): string[] {
  return HERO_SKINS[id] ?? [];
}
